package com.bank.spark.service;

import com.bank.spark.model.Trade;

import java.math.BigDecimal;
import java.util.Map;

// Uses a BROADCAST VARIABLE (the rate map) inside a map-side lookup.
public class CurrencyConverter {

    private final Map<String, BigDecimal> broadcastRates; // sc.broadcast(rates).value()

    public CurrencyConverter(Map<String, BigDecimal> broadcastRates) {
        this.broadcastRates = broadcastRates;  // read-only reference object
    }

    // Convert one trade's amount to INR using the broadcast rate map.
    public BigDecimal toInr(Trade t) {
        BigDecimal rate = broadcastRates.getOrDefault(t.getCurrency(), BigDecimal.ONE);
        return t.getAmount().multiply(rate);
    }
}
