package com.bank.spark.service;

import com.bank.spark.model.Trade;

import java.util.Map;

// Represents a BROADCAST JOIN: the small branch table is broadcast; join is local.
public class BranchEnricher {

    private final Map<String, String> broadcastBranchNames; // broadcast join build side

    public BranchEnricher(Map<String, String> broadcastBranchNames) {
        this.broadcastBranchNames = broadcastBranchNames;
    }

    // "Join" a trade row to the branch name locally — no shuffle of trades.
    public String enrich(Trade t) {
        return t.getTradeId() + " -> branch " + broadcastBranchNames.getOrDefault(t.getBranchId(), "UNKNOWN");
    }
}
