package com.bank.spark;

import com.bank.spark.model.Trade;
import com.bank.spark.service.BranchEnricher;
import com.bank.spark.service.CurrencyConverter;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BroadcastUsageDemo {

    private static final Logger log = Logger.getLogger(BroadcastUsageDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Trade> trades = List.of(
                new Trade("TR1", "USD", new BigDecimal("1000"), "BR-MUM"),
                new Trade("TR2", "EUR", new BigDecimal("500"),  "BR-DEL")
        );

        // BROADCAST VARIABLE: a read-only rate map used inside a map-side lookup.
        Map<String, BigDecimal> rates = Map.of("USD", new BigDecimal("83.20"), "EUR", new BigDecimal("89.50"));
        log.info(() -> "Broadcast VARIABLE: distributing currency rate map (" + rates.size() + " entries) for map-side lookups");
        CurrencyConverter converter = new CurrencyConverter(rates);
        for (Trade t : trades) {
            log.info(t.getTradeId() + " " + t.getAmount() + " " + t.getCurrency()
                    + " -> INR " + converter.toInr(t));
        }

        // BROADCAST JOIN: a small branch table broadcast to attach names in a relational join.
        Map<String, String> branches = Map.of("BR-MUM", "Mumbai Main", "BR-DEL", "Delhi Central");
        log.info(() -> "Broadcast JOIN: broadcasting branch dimension (" + branches.size() + " rows) to avoid shuffling trades");
        BranchEnricher enricher = new BranchEnricher(branches);
        for (Trade t : trades) {
            log.info(enricher.enrich(t));
        }

        log.info("Variable = general read-only object for map-side logic; Join = relational join optimization.");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                record.getMillis(), record.getLevel().getName(), record.getMessage());
    }
}
